solution.solution.cpp:
#include <algorithm>
#include <sstream>
#include <string>
#include <vector>

struct Spawn { double time; std::string kind; };

class Waves
{
public:
    bool load(const std::string& text, std::string& error)
    {
        std::vector<std::vector<Spawn>> waves;
        std::istringstream in{ text };
        int number{ 0 };
        for (std::string line; std::getline(in, line);)
        {
            ++number;
            if (!line.empty() && line.back() == '\r') line.pop_back();
            std::istringstream words{ line };
            std::string first;
            if (!(words >> first) || first[0] == '#') continue;
            if (first == "wave")
            {
                int n{ 0 };
                std::string extra;
                if (!(words >> n) || (words >> extra) || n != static_cast<int>(waves.size()) + 1)
                {
                    error = "line " + std::to_string(number) + ": expected wave " + std::to_string(waves.size() + 1);
                    return false;
                }
                waves.emplace_back();
                continue;
            }
            if (waves.empty()) { error = "line " + std::to_string(number) + ": group outside a wave"; return false; }
            std::istringstream group{ line };
            double time{ 0 }, interval{ 0 };
            std::string kind, extra;
            int count{ 0 };
            if (!(group >> time >> kind >> count >> interval) || (group >> extra) || count < 1 || interval < 0 || time < 0)
            {
                error = "line " + std::to_string(number) + ": bad group";
                return false;
            }
            for (int i{ 0 }; i < count; ++i) waves.back().push_back({ time + i * interval, kind });
        }
        for (auto& w : waves) std::stable_sort(w.begin(), w.end(), [](const Spawn& a, const Spawn& b) { return a.time < b.time; });
        m_waves = std::move(waves);
        return true;
    }

    int count() const { return static_cast<int>(m_waves.size()); }

    std::vector<Spawn> schedule(int wave) const
    {
        if (wave < 1 || wave > count()) return {};
        return m_waves[static_cast<std::size_t>(wave - 1)];
    }

    std::vector<std::string> spawnsBetween(int wave, double from, double to) const
    {
        std::vector<std::string> out;
        for (const Spawn& s : schedule(wave)) if (s.time > from && s.time <= to) out.push_back(s.kind);
        return out;
    }

    double length(int wave) const
    {
        const auto s{ schedule(wave) };
        return s.empty() ? 0.0 : s.back().time;
    }

private:
    std::vector<std::vector<Spawn>> m_waves;
};

unitTests:
using Kinds = std::vector<std::string>;
const std::string data =
    "# time kind count interval\r\n"
    "wave 1\r\n0 walker 4 1.0\r\n6 walker 4 0.5\r\n"
    "\r\nwave 2\r\n0 walker 3 0.6\r\n1.2 charger 2 2.0\r\n";
TEST("loading") {
    Waves w; std::string err; CHECK(w.load(data, err)); CHECK_EQ(w.count(), 2);
    CHECK_EQ(w.schedule(1).size(), std::size_t{ 8 }); CHECK_NEAR(w.length(1), 7.5, 1e-9); CHECK_NEAR(w.length(2), 3.2, 1e-9);
}
TEST("sorted by time, file order for ties") {
    Waves w; std::string err; w.load(data, err); const auto s = w.schedule(2);
    CHECK_EQ(s.size(), std::size_t{ 5 }); CHECK_EQ(s[2].kind, std::string("walker")); CHECK_NEAR(s[2].time, 1.2, 1e-9); CHECK_EQ(s[3].kind, std::string("charger")); CHECK_EQ(s[4].kind, std::string("charger"));
}
TEST("what spawns this frame") {
    Waves w; std::string err; w.load(data, err);
    CHECK_EQ(w.spawnsBetween(1, -1, 0), (Kinds{ "walker" })); CHECK_EQ(w.spawnsBetween(1, 0, 0.99), (Kinds{}));
    CHECK_EQ(w.spawnsBetween(1, 2.5, 6.5), (Kinds{ "walker", "walker", "walker" })); CHECK_EQ(w.spawnsBetween(2, 1.0, 1.2), (Kinds{ "walker", "charger" }));
    CHECK(w.spawnsBetween(3, 0, 100).empty()); CHECK_NEAR(w.length(3), 0.0, 1e-9);
}
TEST("errors keep the old waves") {
    Waves w; std::string err; w.load(data, err);
    CHECK(!w.load("wave 2\n", err)); CHECK_EQ(err, std::string("line 1: expected wave 1"));
    CHECK(!w.load("# x\n0 walker 1 1\n", err)); CHECK_EQ(err, std::string("line 2: group outside a wave"));
    CHECK(!w.load("wave 1\n0 walker 0 1\n", err)); CHECK_EQ(err, std::string("line 2: bad group"));
    CHECK(!w.load("wave 1\n0 walker 2 1 extra\n", err)); CHECK_EQ(err, std::string("line 2: bad group"));
    CHECK(!w.load("wave 1\nwave 3\n", err)); CHECK_EQ(err, std::string("line 2: expected wave 2"));
    CHECK_EQ(w.count(), 2);
}

